"""Original snakebite questions: assessment, physiology and antivenom decisions."""
from qbank_authoring import question,ref
rows=[]
WH=ref('WHO South-East Asia snakebite management guidelines, second edition','https://www.who.int/publications/i/item/9789290225300')
IN=ref('Government of India snakebite standard treatment guidelines','https://clinicalestablishments.mohfw.gov.in/sites/default/files/standard-treatment-guidelines/3941.pdf')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Which first-aid measure is appropriate after a suspected snakebite in a rural Indian setting?', 'Keep the patient still, immobilize the bitten limb and arrange prompt transport',[
 ('Apply a tight arterial tourniquet','This can cause ischemia and complicate subsequent management.'),('Incise and suction the bite before transport','These measures injure tissue, risk infection and delay definitive care.'),('Encourage running to the nearest facility','Muscle activity can accelerate lymphatic venom spread.')],
 'Reduce movement and avoid harmful procedures','**Safe immobilization and rapid access to care are the priorities.**',['Remove constricting objects before swelling increases.','Do not attempt to capture or handle the snake.'],'**Observe breathing and consciousness during transport.**',['Use a regional first-aid protocol; pressure immobilization is not a universal instruction for all Indian snakebites.','Provide basic respiratory support when required.'],[['Useful','Stillness, splint and transport'],['Harmful','Cutting/suction/tight tourniquet'],['Safety','Do not handle the snake']],[IN,WH])

q('Which finding is a clear indication for appropriate antivenom after a suspected snakebite?', 'Progressive systemic neurotoxicity with ptosis and bulbar weakness',[
 ('Fang marks alone without clinical or laboratory envenoming','Marks do not establish venom injection or systemic need.'),('Anxiety alone with normal serial assessment','Anxiety is common and does not itself justify antivenom.'),('A photograph of a venomous species with no evidence of envenoming','Species risk informs monitoring, but not every bite delivers venom.')],
 'Treat envenoming rather than the appearance of the bite','**Systemic neurotoxicity is a major antivenom indication.**',['Coagulopathy, bleeding, cardiovascular toxicity and selected severe local progression are other indications.','Use an effective product for the likely species and geography.'],'**Give antivenom while preparing respiratory support.**',['Do not wait for respiratory arrest.','Antivenom does not replace ventilation or other organ support.'],[['Fang marks','Exposure clue'],['Systemic toxicity','Treatment indication'],['Airway weakness','Immediate support risk']],[WH,IN],style='clinical_scenario')

q('A child and an adult have comparable systemic envenoming from the same snake species. Which antivenom-dose principle is correct?', 'The venom-neutralizing dose is generally the same because it depends on venom burden rather than patient weight',[
 ('Give the child half the adult vial dose solely by age','The snake does not inject venom in proportion to body weight.'),('Use a body-surface-area oncology formula','That is not the standard neutralizing-dose principle.'),('Give no antivenom to children because reaction risk is higher','Children may have severe envenoming and require indicated treatment.')],
 'Neutralize an injected toxin burden','**Antivenom dosing is based on the expected venom and product potency.**',['Children may experience greater toxicity from a comparable inoculum.','Infusion volume and fluid tolerance still require pediatric adjustment.'],'**Follow the product and regional treatment protocol.**',['Monitor for reactions and progression.','Do not substitute a fixed universal vial count across products and species.'],[['Dose basis','Venom burden/potency'],['Age','Does not justify reducing neutralizing dose'],['Fluid volume','Adjust to patient tolerance']],[WH,IN])

q('What is essential for a technically valid 20-minute whole-blood clotting test?', 'Fresh venous blood in a new, clean, dry ordinary glass vessel left undisturbed',[
 ('Blood collected into an EDTA tube','Anticoagulant invalidates the intended clotting observation.'),('A wet plastic syringe as the preferred universal container','Surface and contamination differences can make the result unreliable.'),('Continuous shaking for twenty minutes','The test requires an undisturbed sample before assessment.')],
 'Simple tests still require standardized technique','**An incorrect vessel or contamination can create a false result.**',['Use the specified volume and local protocol.','Interpret the result alongside examination and laboratory coagulation tests when available.'],'**Repeat assessment when evolving envenoming remains possible.**',['A single normal early test does not exclude later coagulopathy.','Do not delay urgent treatment for clear systemic envenoming while awaiting this test.'],[['Container','Clean dry ordinary glass'],['Sample','Fresh blood without anticoagulant'],['Interpretation','Technique and clinical context']],[WH,IN])

q('After a viper bite, blood is incoagulable with low fibrinogen and elevated fibrin-degradation markers. Which process best describes this?', 'Venom-induced consumption coagulopathy',[
 ('Immune thrombocytopenia alone','An isolated platelet disorder does not explain the major coagulation-factor/fibrinogen consumption.'),('Hemophilia A acquired solely from the bite','The acute broad consumption pattern is different from isolated factor VIII deficiency.'),('Vitamin K deficiency as the immediate venom mechanism','Venom procoagulant activity can consume factors directly.')],
 'VICC is not simply synonymous with every form of DIC','**Venom toxins can activate coagulation and rapidly consume clotting substrates.**',['Bleeding risk and laboratory evolution require serial assessment.','Endothelial injury, thrombocytopenia and other mechanisms may coexist.'],'**Neutralize the responsible venom and provide targeted support for significant bleeding.**',['Blood products alone cannot neutralize circulating venom.','Interpret persistent abnormalities according to timing, ongoing toxicity and the protocol.'],[['Mechanism','Venom-mediated coagulation activation'],['Result','Factor/fibrinogen depletion'],['Specific therapy','Effective antivenom']],[WH],style='clinical_scenario')

q('A farmer develops ptosis, ophthalmoplegia and bulbar weakness after a nocturnal bite with little local swelling. Which syndrome requires immediate attention?', 'Neuroparalytic envenoming with impending respiratory failure',[
 ('A dry bite established by minimal swelling','Minimal local injury does not exclude severe systemic neurotoxicity.'),('A purely local allergic reaction','The cranial and bulbar weakness indicates neurological dysfunction.'),('Hemotoxicity excluded permanently by a normal first clotting test','A normal early test does not settle the entire envenoming syndrome.')],
 'Local severity does not predict respiratory safety','**Some neurotoxic bites produce little visible local reaction.**',['Cranial weakness can precede respiratory muscle failure.','Pulse oximetry can remain reassuring until ventilatory failure is advanced.'],'**Assess airway protection and ventilation repeatedly and give indicated antivenom.**',['Support breathing before arrest occurs.','Do not require capture or definitive species identification before syndrome-based treatment.'],[['Local swelling','May be slight'],['Bulbar weakness','Airway risk'],['Support','Early ventilatory assessment']],[IN,WH],style='clinical_scenario')

q('Why may established krait-related paralysis persist despite adequate antivenom?', 'Presynaptic toxin injury may not reverse promptly after circulating venom is neutralized',[
 ('Persistent weakness always proves that more antivenom will immediately reverse it','Established terminal injury can outlast free venom.'),('Antivenom has no role before paralysis develops','Early neutralization can prevent further venom action.'),('Normal consciousness excludes severe neuromuscular paralysis','Patients can remain conscious despite profound paralysis.')],
 'Neutralization and functional recovery occur on different timescales','**Antivenom binds accessible venom but cannot instantly repair injured nerve terminals.**',['Postsynaptic and presynaptic neurotoxins have different reversibility patterns.','Ventilation may be needed until neuromuscular recovery.'],'**Judge further antivenom by ongoing envenoming and the protocol, not weakness alone.**',['Prevent ventilator-related complications and provide rehabilitation.','Communicate with a conscious paralyzed patient.'],[['Free venom','Neutralizable'],['Established injury','Recovery may take time'],['Treatment bridge','Mechanical ventilation']],[WH])

q('In which snakebite neurotoxicity pattern is an atropine-protected neostigmine trial most mechanistically plausible?', 'Predominantly postsynaptic neuromuscular blockade',[
 ('Irreversible presynaptic terminal destruction as a reliably responsive state','Increasing acetylcholine cannot reliably reverse established terminal injury.'),('Venom-induced consumption coagulopathy alone','An anticholinesterase does not replace consumed clotting factors.'),('Severe local tissue necrosis without weakness','This is not a neuromuscular-junction indication.')],
 'A physiological trial is not a substitute for airway support','**Increasing acetylcholine can help selected postsynaptic blockade.**',['Atropine limits muscarinic adverse effects.','Response varies with the venom and injury pattern.'],'**Use the recommended monitored trial without delaying antivenom or ventilation.**',['Document objective strength/respiratory response.','Do not continue ineffective treatment indefinitely.'],[['Potential response','Postsynaptic blockade'],['Protection','Atropine'],['Nonresponse','Does not remove ventilation need']],[WH,IN])

q('Which statement about Indian polyvalent antivenom coverage is correct?', 'A product raised against the common big-four species does not guarantee effective neutralization of every regional snake venom',[
 ('Polyvalent means universal coverage of all venomous snakes','Coverage is limited by the immunizing venoms and cross-neutralization evidence.'),('Every viper species has identical toxin composition','Venom composition varies across species and geography.'),('The same vial dose is interchangeable across all global antivenom products','Potency, specificity and formulation differ.')],
 'Match the antidote to the plausible venom','**Species and geographic variation can create coverage gaps.**',['Clinical syndrome guides urgent treatment when identification is uncertain.','Lack of response may reflect established injury, insufficient neutralization or an unmatched venom.'],'**Use regional expertise and an approved effective product.**',['Do not infer efficacy from the word polyvalent alone.','Continue organ support even when specific neutralization options are limited.'],[['Product','Defined immunizing venoms'],['Variation','Species/geography'],['Decision','Local efficacy and syndrome']],[WH,IN])

q('Soon after antivenom starts, a patient develops wheeze, urticaria and hypotension with a pulse. Which immediate treatment is most important?', 'Intramuscular epinephrine with airway, oxygen and circulatory support',[
 ('Antihistamine alone while continuing the infusion unchanged','Antihistamines do not reverse anaphylactic shock or airway compromise.'),('A skin test before giving any rescue drug','Testing would delay life-saving treatment and is not the emergency priority.'),('A large unmonitored IV epinephrine bolus as routine first-line treatment','IM epinephrine is the standard initial route for anaphylaxis with a pulse; IV use requires an appropriate expert monitored strategy.')],
 'Treat the reaction immediately','**Antivenom can trigger early systemic hypersensitivity reactions.**',['Temporarily stop the infusion and resuscitate.','Life-threatening envenoming may still require cautious resumption after reaction control under expert monitoring.'],'**Do not let fear of a reaction prevent indicated antivenom.**',['Prepare treatment and monitoring before infusion.','Persistent instability may require an epinephrine infusion in an appropriate critical-care setting.'],[['Reaction','Anaphylaxis'],['First-line with pulse','IM epinephrine'],['Antivenom','Reassess resumption after stabilization']],[WH,IN],style='clinical_scenario')

q('Does a negative antivenom skin test reliably exclude a serious infusion reaction?', 'No; it is not a reliable safety test and should not delay indicated antivenom',[
 ('Yes; a negative result eliminates the need for monitoring','Serious reactions can still occur.'),('Yes; it predicts all non-IgE-mediated reactions','Many early antivenom reactions are not predicted by such testing.'),('No; therefore antivenom should never be used','A potentially serious reaction risk does not negate indicated life-saving treatment.')],
 'Preparation is more useful than false reassurance','**Skin testing has poor predictive value for antivenom reactions.**',['Emergency drugs, personnel and monitoring should be available.','Patients need observation during and after treatment.'],'**Use antivenom on clinical indications with a reaction-management plan.**',['Document prior reactions and relevant risk history.','Treat an actual reaction promptly rather than relying on a test result.'],[['Skin test','Poor prediction'],['Safety','Readiness and monitoring'],['Treatment','Clinical indication']],[WH,IN])

q('A patient develops fever, rash, arthralgia and lymphadenopathy 8 days after antivenom. Which diagnosis best fits?', 'Serum sickness',[
 ('Immediate anaphylaxis as the usual timing','Anaphylaxis is typically an acute early reaction.'),('Recurrent venom neurotoxicity','This does not explain the delayed systemic inflammatory symptom pattern.'),('A mandatory bacterial wound infection diagnosis','Infection needs evaluation when indicated but is not established by this classic delayed syndrome.')],
 'Distinguish early infusion reactions from delayed immune-complex disease','**Serum sickness can follow exposure to heterologous proteins.**',['Timing over days and the rash/arthralgia pattern are clues.','Exclude infection and other drug reactions according to the presentation.'],'**Treat severity and provide return advice after antivenom.**',['Antihistamines and selected corticosteroid treatment may be appropriate under clinical assessment.','Record the reaction for future care.'],[['Early reaction','Minutes to hours'],['Serum sickness','Delayed days'],['Pattern','Fever, rash, joint symptoms']],[WH],style='clinical_scenario')
